def rotate_list(lst, num_positions):
    """
    Rotate a list by num_positions.

    Args:
        lst (list): The list to be rotated.
        num_positions (int): The position where to rotate the list.

    Returns:
        list: The rotated list.

    Raises:
        ValueError: If num_positions is negative, zero or larger than lst.size().
    """

    if num_positions == 0:
        return lst

    if num_positions < 0:
        return rotate_list(-num_positions, lst)
    elif num_positions > lst.size():
        return rotate_list(lst, num_positions - lst.size())
    elif num_positions < 0:
        return rotate_list(-num_positions, lst)
    else:
        return lst + lst[::-num_positions]

# Example usage:
lst = [1, 2, 3, 4, 5]
lst_rotated = rotate_list(lst, 2)
print(lst_rotated)  # Output: [4, 5, 1, 2, 3]
